<style>
    .content-actions{display:flex;gap:8px;flex-wrap:wrap}.content-filter{display:flex;gap:9px;flex-wrap:wrap;align-items:end}.content-field{display:grid;gap:6px;min-width:160px;flex:1}.content-field.full{grid-column:1/-1}.content-field label{color:#52675a;font-size:12px;font-weight:800}.content-input,.content-textarea,.content-select{width:100%;border:1px solid #d6e1d5;border-radius:8px;background:#fff;color:#173425;padding:10px 11px;font:inherit}.content-input,.content-select{height:43px}.content-textarea{min-height:100px;resize:vertical}.content-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.content-form-stack{display:grid;gap:14px}.content-thumb{width:108px;height:66px;object-fit:cover;border:1px solid #dfe7dc;border-radius:6px;background:#f5f7f3}.content-badge{display:inline-flex;border-radius:999px;padding:4px 8px;font-size:11px;font-weight:800;background:#edf5ea;color:#3f744e}.content-badge.off{background:#f1f1ef;color:#747872}.content-help{color:#718078;font-size:11px;line-height:1.55}.content-check{display:flex;align-items:center;gap:8px;font-weight:700;color:#365042}.content-check input{width:18px;height:18px;accent-color:#397a50}.content-card-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.content-card{border:1px solid #dce6d9;border-radius:8px;background:#fff;padding:13px;display:grid;grid-template-columns:108px minmax(0,1fr);gap:12px}.content-card h3{font-size:14px;margin:0 0 5px}.content-card p{font-size:12px;color:#6a7a70;margin:0 0 8px;line-height:1.45}.content-editor{min-height:360px;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:13px;line-height:1.55}@media(max-width:760px){.content-form-grid,.content-card-list{grid-template-columns:1fr}.content-field.full{grid-column:auto}.content-card{grid-template-columns:82px minmax(0,1fr)}.content-thumb{width:82px;height:58px}}
</style>
